/**
 * Unit tests for model-switch-telemetry (PostModelSwitch, CC 2.1.251, #3789).
 */

import { describe, test, expect, vi, beforeEach } from 'vitest';
import { mockCommonBasic } from '../fixtures/mock-common.js';

vi.mock('../../lib/common.js', () => mockCommonBasic({}));

const appendAnalytics = vi.fn();
vi.mock('../../lib/analytics.js', () => ({
  appendAnalytics: (...args: unknown[]) => appendAnalytics(...args),
  hashProject: vi.fn(() => 'p-hash'),
}));

import { modelSwitchTelemetry, MODEL_SWITCH_ANALYTICS_FILE } from '../../lifecycle/model-switch-telemetry.js';
import type { HookInput } from '../../types.js';

/** Verbatim shape of the 2.1.251 PostModelSwitch payload (paths elided). */
const captured = {
  session_id: 'bc4be102-5954-4d73-9407-b3d40f785627',
  transcript_path: '/tmp/t.jsonl',
  cwd: '/tmp/hookdump',
  prompt_id: '58e08989-5d21-42da-befd-6762aef60a56',
  hook_event_name: 'PostModelSwitch',
  from_model: 'claude-sonnet-5',
  to_model: 'claude-opus-5',
  requested_model: 'claude-opus-5',
  source: 'command',
  context_tokens: 0,
  prompt_cache_warm: false,
  cache_ttl: '1h',
  estimated_cache_write_usd: 0,
  pricing: 'catalog',
};

describe('model-switch-telemetry (PostModelSwitch)', () => {
  beforeEach(() => { appendAnalytics.mockClear(); });

  test('records one analytics line with the measured fields and never emits context', () => {
    const r = modelSwitchTelemetry(captured as unknown as HookInput);
    expect(r.continue).toBe(true);
    expect(r.hookSpecificOutput).toBeUndefined();
    expect(appendAnalytics).toHaveBeenCalledTimes(1);
    const [file, entry] = appendAnalytics.mock.calls[0] as [string, Record<string, unknown>];
    expect(file).toBe(MODEL_SWITCH_ANALYTICS_FILE);
    expect(entry).toMatchObject({
      pid: 'p-hash',
      session_id: captured.session_id,
      from_model: 'claude-sonnet-5',
      to_model: 'claude-opus-5',
      requested_model: 'claude-opus-5',
      source: 'command',
      context_tokens: 0,
      prompt_cache_warm: false,
      cache_ttl: '1h',
      estimated_cache_write_usd: 0,
      pricing: 'catalog',
      to_premium_tier: false,
    });
    expect(typeof entry.ts).toBe('string');
  });

  test('flags a premium-tier destination', () => {
    modelSwitchTelemetry({ ...captured, to_model: 'claude-fable-5', requested_model: 'claude-fable-5' } as unknown as HookInput);
    const [, entry] = appendAnalytics.mock.calls[0] as [string, Record<string, unknown>];
    expect(entry.to_premium_tier).toBe(true);
  });

  test('a payload without to_model records nothing', () => {
    const r = modelSwitchTelemetry({ hook_event_name: 'PostModelSwitch', session_id: 's' } as unknown as HookInput);
    expect(r.continue).toBe(true);
    expect(appendAnalytics).not.toHaveBeenCalled();
  });

  test('an analytics write failure is swallowed', () => {
    appendAnalytics.mockImplementationOnce(() => { throw new Error('disk full'); });
    const r = modelSwitchTelemetry(captured as unknown as HookInput);
    expect(r.continue).toBe(true);
  });
});
